220: // DeleteKbDocument DELETE /v1/kb/kbs/:kb_id/documents 单文档数据退场。
221: // 鉴权同 push(平台 API Key → teamID);同步调用离线 purge_doc 算子
222: // 清理向量/正排/S3,幂等(重复删除返回全零统计)。仅 api_push 型 KB 可用,
223: // feishu 型文档生命周期归源端同步 diff。
224: func DeleteKbDocument(c *gin.Context) (interface{}, error) {
225: 	teamID, err := teamFromCtx(c)
226: 	if err != nil {
227: 		return nil, err
228: 	}
229: 	deps := DatasourceDeps
230: 	if !requestctx.CanWriteDocuments(c.Request.Context(), c.Param("kb_id")) {
231: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_TEAM_FORBIDDEN, "team API key document scope is required")
232: 	}
233: 	if len(c.Request.URL.Query()["source"]) > 1 {
234: 		return nil, xwikiInvalid("ambiguous document source")
235: 	}
236: 	if source := c.Query("source"); source == importTypeXWiki {
237: 		return publicXWikiDocument(c, true)
238: 	} else if source != "" && source != "upload" {
239: 		return nil, xwikiInvalid("unsupported document source")
240: 	}
241: 
242: 	docID := strings.TrimSpace(c.Query("doc_id"))
243: 	if docID == "" {
244: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_INVALID_PARAM,
245: 			"query param doc_id is required")
246: 	}
247: 	if !safeIDPattern.MatchString(docID) {
248: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_INVALID_PARAM,
249: 			"invalid doc_id: only letters, digits, dot, underscore, hyphen (max 128)")
250: 	}
251: 
252: 	// 同步等待算子执行,冷启动留余量
253: 	ctx, cancel := context.WithTimeout(c.Request.Context(), 30*time.Second)
254: 	defer cancel()
255: 	entry, err := loadKbEntry(ctx, deps, teamID, c.Param("kb_id"))
256: 	if err != nil {
257: 		return nil, err
258: 	}
259: 	if entry.ImportType != importTypeAPIPush {
260: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_INVALID_PARAM,
261: 			"only api_push knowledge bases support document deletion (import_type is "+entry.ImportType+")")
262: 	}
263: 	if err := rejectManagedXWikiDocument(ctx, teamID, entry.KbID, docID); err != nil {
264: 		return nil, err
265: 	}
266: 
267: 	if deps.Invoke == nil {
268: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_FAIL, "purge operator not configured")
269: 	}
270: 	result, err := deps.Invoke.InvokePurgeDoc(ctx, teamID, entry.KbID, docID)
271: 	if err != nil {
272: 		var sourceErr *clients.SourceOperationError
273: 		if errors.As(err, &sourceErr) {
274: 			if sourceErr.Code == "source_conflict" {
275: 				return nil, xwikiConflict("document belongs to another source")
276: 			}
277: 			return nil, sourceBusy("document purge is still pending")
278: 		}
279: 		logs.WarnCtx(ctx, "purge_doc invoke failed",
280: 			zap.String("team_id", teamID), zap.String("kb_id", entry.KbID),
281: 			zap.String("doc_id", docID), zap.Error(err))
282: 		return nil, modelCommon.NewHandlerError(constants.ERR_CODE_FAIL, "document purge failed")

